// Hàm ghi buffer xuống thẻ SD
void writeToSD() {
    dataFile = SD.open(filename, FILE_APPEND);
    if (dataFile) {
        for (int i = 0; i < bufferSize; i++) {
            dataFile.println(dataBuffer[i]);
        }
        dataFile.close();
        Serial.println("Đã ghi dữ liệu vào SD!");
    } else {
        Serial.println("Lỗi mờ file!");
    }
}
